-- Generated by db/generate_schema.py from real data/*.csv headers and values.
-- Synthetic operational sandbox only. Portable SQLite/PostgreSQL types; no clinical policies are inferred.

CREATE TABLE "appointments" (
  "appointment_id" TEXT,
  "patient_id" TEXT,
  "department_id" TEXT,
  "scheduled_start" TIMESTAMP,
  "duration_minutes" INTEGER,
  "appointment_type" TEXT,
  "status" TEXT,
  "wait_minutes" NUMERIC,
  PRIMARY KEY ("appointment_id"),
  FOREIGN KEY ("patient_id") REFERENCES "patients" ("patient_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id"),
  CHECK ("duration_minutes" IS NULL OR "duration_minutes" >= 0),
  CHECK ("wait_minutes" IS NULL OR "wait_minutes" >= 0)
);

CREATE TABLE "bed_status_events" (
  "event_id" TEXT,
  "bed_id" TEXT,
  "event_time" TIMESTAMP,
  "status" TEXT,
  "reason" TEXT,
  "end_time" TIMESTAMP,
  PRIMARY KEY ("event_id"),
  FOREIGN KEY ("bed_id") REFERENCES "beds" ("bed_id")
);

CREATE TABLE "bed_stays" (
  "bed_stay_id" TEXT,
  "visit_id" TEXT,
  "bed_id" TEXT,
  "start_time" TIMESTAMP,
  "end_time" TIMESTAMP,
  "transfer_reason" TEXT,
  "department_id" TEXT,
  "bed_type" TEXT,
  "discharge_order_time" TIMESTAMP,
  "bed_ready_time" TIMESTAMP,
  "data_source" TEXT,
  PRIMARY KEY ("bed_stay_id"),
  FOREIGN KEY ("visit_id") REFERENCES "visits" ("visit_id"),
  FOREIGN KEY ("bed_id") REFERENCES "beds" ("bed_id"),
  CHECK ("end_time" IS NULL OR "end_time" >= "start_time")
);

CREATE TABLE "beds" (
  "bed_id" TEXT,
  "room_id" TEXT,
  "bed_type" TEXT,
  "status" TEXT,
  "is_isolation_capable" BOOLEAN,
  PRIMARY KEY ("bed_id"),
  FOREIGN KEY ("room_id") REFERENCES "rooms" ("room_id"),
  CHECK ("is_isolation_capable" IN (TRUE, FALSE))
);

CREATE TABLE "calendar_days" (
  "date" DATE,
  "dow" INTEGER,
  "is_weekend" BOOLEAN,
  "is_holiday" BOOLEAN,
  "holiday_name" TEXT,
  "is_ramadan" BOOLEAN,
  "is_eid" BOOLEAN,
  "season" TEXT,
  "school_term" TEXT,
  "days_to_holiday" INTEGER,
  PRIMARY KEY ("date"),
  CHECK ("is_weekend" IN (TRUE, FALSE)),
  CHECK ("is_holiday" IN (TRUE, FALSE)),
  CHECK ("is_ramadan" IN (TRUE, FALSE)),
  CHECK ("is_eid" IN (TRUE, FALSE))
);

CREATE TABLE "calibration_params" (
  "group_type" TEXT,
  "group_value" TEXT,
  "parameter" TEXT,
  "stat" TEXT,
  "value" NUMERIC,
  "n" INTEGER,
  "unit" TEXT,
  PRIMARY KEY ("group_type", "group_value", "parameter", "stat")
);

CREATE TABLE "cost_rates" (
  "cost_rate_id" TEXT,
  "cost_category" TEXT,
  "department_id" TEXT,
  "unit" TEXT,
  "rate_egp" INTEGER,
  "effective_from" DATE,
  "effective_to" TEXT,
  PRIMARY KEY ("cost_rate_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id")
);

CREATE TABLE "daily_metrics" (
  "metric_id" TEXT,
  "metric_date" DATE,
  "department_id" TEXT,
  "arrivals_count" INTEGER,
  "admissions_count" INTEGER,
  "discharges_count" INTEGER,
  "occupied_beds" INTEGER,
  "staffed_beds" INTEGER,
  "occupancy_rate" NUMERIC,
  "avg_wait_minutes" NUMERIC,
  "p90_wait_minutes" NUMERIC,
  "er_queue_peak" NUMERIC,
  "surgeries_scheduled" NUMERIC,
  "surgeries_completed" NUMERIC,
  "or_utilization_rate" NUMERIC,
  "staff_absence_count" INTEGER,
  "overtime_hours" NUMERIC,
  "avg_occupied_beds" NUMERIC,
  "peak_occupied_beds" NUMERIC,
  "boarders_peak" NUMERIC,
  "lwbs_count" NUMERIC,
  "transfers_out" NUMERIC,
  "admit_requests" NUMERIC,
  "unmet_demand" NUMERIC,
  "er_pressure_index" NUMERIC,
  "er_hours_at_capacity" NUMERIC,
  "is_capacity_capped" BOOLEAN,
  "pending_discharges" NUMERIC,
  "icu_free_beds" NUMERIC,
  "or_rooms_open" NUMERIC,
  "surgeries_cancelled" NUMERIC,
  "resource_utilization_rate" NUMERIC,
  PRIMARY KEY ("metric_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id"),
  CHECK ("occupancy_rate" IS NULL OR "occupancy_rate" BETWEEN 0 AND 1),
  CHECK ("avg_wait_minutes" IS NULL OR "avg_wait_minutes" >= 0),
  CHECK ("p90_wait_minutes" IS NULL OR "p90_wait_minutes" >= 0),
  CHECK ("or_utilization_rate" IS NULL OR "or_utilization_rate" BETWEEN 0 AND 1),
  CHECK ("is_capacity_capped" IN (TRUE, FALSE)),
  CHECK ("resource_utilization_rate" IS NULL OR "resource_utilization_rate" BETWEEN 0 AND 1)
);

CREATE TABLE "data_quality_report" (
  "check_name" TEXT,
  "status" TEXT,
  "value" TEXT,
  "threshold" TEXT,
  PRIMARY KEY ("check_name")
);

CREATE TABLE "decisions" (
  "decision_id" TEXT,
  "created_at" TIMESTAMP,
  "simulation_id" TEXT,
  "bottleneck" TEXT,
  "recommendation" TEXT,
  "expected_wait_change_pct" NUMERIC,
  "expected_occupancy_change_pct" NUMERIC,
  "expected_cost_change_egp" NUMERIC,
  "expected_revenue_risk_change_egp" NUMERIC,
  "confidence_score" NUMERIC,
  "assumptions_json" TEXT,
  "approval_status" TEXT,
  "approved_by_role" TEXT,
  "approved_at" TIMESTAMP,
  "audit_notes" TEXT,
  PRIMARY KEY ("decision_id"),
  FOREIGN KEY ("simulation_id") REFERENCES "simulation_runs" ("simulation_id")
);

CREATE TABLE "departments" (
  "department_id" TEXT,
  "department_name" TEXT,
  "department_name_ar" TEXT,
  "department_type" TEXT,
  "is_active" BOOLEAN,
  PRIMARY KEY ("department_id"),
  CHECK ("is_active" IN (TRUE, FALSE)),
  CHECK ("department_type" IN ('CLINIC', 'ER', 'ICU', 'IMAGING', 'LAB', 'OR', 'WARD'))
);

CREATE TABLE "er_events" (
  "er_event_id" TEXT,
  "visit_id" TEXT,
  "event_time" TIMESTAMP,
  "event_type" TEXT,
  "queue_minutes" INTEGER,
  "notes_code" TEXT,
  PRIMARY KEY ("er_event_id"),
  FOREIGN KEY ("visit_id") REFERENCES "visits" ("visit_id")
);

CREATE TABLE "financial_daily" (
  "financial_id" TEXT,
  "metric_date" DATE,
  "department_id" TEXT,
  "revenue_egp" NUMERIC,
  "labor_cost_egp" NUMERIC,
  "supply_cost_egp" NUMERIC,
  "overtime_cost_egp" NUMERIC,
  "cancelled_procedure_risk_egp" NUMERIC,
  PRIMARY KEY ("financial_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id")
);

CREATE TABLE "financial_risk_daily" (
  "metric_date" DATE,
  "department_id" TEXT,
  "cancelled_surgery_margin_at_risk_egp" NUMERIC,
  "delayed_surgery_margin_loss_egp" NUMERIC,
  "lwbs_revenue_at_risk_egp" NUMERIC,
  "boarding_cost_egp" NUMERIC,
  "total_revenue_at_risk_egp" NUMERIC,
  PRIMARY KEY ("metric_date", "department_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id")
);

CREATE TABLE "forecast_evaluation" (
  "run_group" TEXT,
