  "in_interval" BOOLEAN,
  "origin_time" DATE,
  "target_day_capped" NUMERIC,
  PRIMARY KEY ("forecast_id"),
  FOREIGN KEY ("run_id") REFERENCES "forecast_runs" ("run_id"),
  CHECK ("in_interval" IN (TRUE, FALSE))
);

CREATE TABLE "forecast_runs" (
  "run_id" TEXT,
