CREATE TABLE "hourly_forecast_evaluation" (
  "target_metric" TEXT,
  "model_name" TEXT,
  "n" INTEGER,
  "mae" NUMERIC,
  "wape" NUMERIC,
  "mape_floor" NUMERIC,
  "mape_floor_value" INTEGER,
