CREATE TABLE "hourly_forecast_results" (
  "predicted_value" NUMERIC,
  "actual_value" NUMERIC,
  "target_metric" TEXT,
  "model_name" TEXT,
  "forecast_for" TIMESTAMP,
  "origin_time" DATE,
  "lead_hours" INTEGER,
  "lower_bound" NUMERIC,
  "upper_bound" NUMERIC,
  "error_value" NUMERIC,
  PRIMARY KEY ("target_metric", "model_name", "forecast_for", "origin_time")
);

CREATE TABLE "hourly_metrics" (
