  "queue_len" NUMERIC,
  "avg_wait" NUMERIC,
  PRIMARY KEY ("hour_ts", "department_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id")
);

CREATE TABLE "latent_events" (
  "date" DATE,
  "surge_type" TEXT,
  "demand_multiplier" NUMERIC,
  PRIMARY KEY ("date", "surge_type")
);

CREATE TABLE "nurse_coverage_by_unit_shift_weekday" (
  "period" TEXT,
  "unit" TEXT,
