  "covered_shifts" INTEGER,
  "min_nurses_on_shift" INTEGER,
  "mean_nurses_on_shift" NUMERIC,
  "max_nurses_on_shift" INTEGER,
  "max_required_nurses" INTEGER,
  "max_occupied_or_active_ors" INTEGER,
  "coverage_pct" NUMERIC,
