);

CREATE TABLE "nurse_coverage_shift_detail" (
  "date" DATE,
  "weekday" TEXT,
  "unit" TEXT,
  "shift" TEXT,
  "shift_start" TIMESTAMP,
  "shift_end" TIMESTAMP,
  "period" TEXT,
