);

CREATE TABLE "operating_rooms" (
  "or_id" TEXT,
  "department_id" TEXT,
  "room_name" TEXT,
  "specialty" TEXT,
  "daily_capacity_hours" NUMERIC,
  "is_active" BOOLEAN,
  PRIMARY KEY ("or_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id"),
  CHECK ("daily_capacity_hours" IS NULL OR "daily_capacity_hours" >= 0),
  CHECK ("is_active" IN (TRUE, FALSE))
);

CREATE TABLE "or_availability" (
  "date" DATE,
  "or_id" TEXT,
  "window_start" TIMESTAMP,
  "window_end" TIMESTAMP,
  "availability_status" TEXT,
  "rostered_surgeons" INTEGER,
  "rostered_anesthetists" INTEGER,
  "capacity_minutes" INTEGER,
  "planned_bookings" INTEGER,
  "booked_minutes_with_turnover" INTEGER,
  "free_minutes" INTEGER,
  "largest_free_block_minutes" INTEGER,
