  PRIMARY KEY ("date", "or_id"),
  FOREIGN KEY ("or_id") REFERENCES "operating_rooms" ("or_id"),
  CHECK ("capacity_minutes" IS NULL OR "capacity_minutes" >= 0),
  CHECK ("booked_minutes_with_turnover" IS NULL OR "booked_minutes_with_turnover" >= 0),
  CHECK ("free_minutes" IS NULL OR "free_minutes" >= 0)
);

CREATE TABLE "patients" (
  "patient_id" TEXT,
  "synthetic_age" INTEGER,
  "synthetic_sex" TEXT,
  "synthetic_cohort" TEXT,
  "created_at" TIMESTAMP,
  PRIMARY KEY ("patient_id"),
  CHECK ("synthetic_age" IS NULL OR "synthetic_age" >= 0)
);

CREATE TABLE "policy_documents" (
  "document_id" TEXT,
  "title" TEXT,
  "policy_type" TEXT,
  "department_id" TEXT,
  "version" NUMERIC,
  "effective_from" DATE,
  "effective_to" TEXT,
  "content" TEXT,
  "approved" BOOLEAN,
  "source_label" TEXT,
  PRIMARY KEY ("document_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id"),
