  "booking_end" TIMESTAMP,
  "quantity_reserved" INTEGER,
  "status" TEXT,
  PRIMARY KEY ("booking_id"),
  FOREIGN KEY ("resource_id") REFERENCES "resources" ("resource_id"),
  FOREIGN KEY ("visit_id") REFERENCES "visits" ("visit_id"),
