);

CREATE TABLE "resources" (
  "resource_id" TEXT,
  "department_id" TEXT,
  "resource_name" TEXT,
  "resource_type" TEXT,
  "quantity" INTEGER,
  "status" TEXT,
  PRIMARY KEY ("resource_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id")
);

CREATE TABLE "rooms" (
  "room_id" TEXT,
  "department_id" TEXT,
  "room_name" TEXT,
  "room_type" TEXT,
