  PRIMARY KEY ("room_id"),
  FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id"),
  CHECK ("is_active" IN (TRUE, FALSE))
);

CREATE TABLE "schema_mapping" (
  "table" TEXT,
  "column" TEXT,
  "definition" TEXT,
  "unit" TEXT,
  "required" TEXT,
  "real_source_field" TEXT,
  "transform" TEXT,
  PRIMARY KEY ("table", "column", "definition")
);

CREATE TABLE "simulation_events" (
  "simulation_event_id" TEXT,
  "simulation_id" TEXT,
  "event_time" TIMESTAMP,
  "entity_type" TEXT,
  "entity_id" TEXT,
  "event_type" TEXT,
  "department_id" TEXT,
  "value_numeric" TEXT,
  "details_json" TEXT,
  PRIMARY KEY ("simulation_event_id"),
  FOREIGN KEY ("simulation_id") REFERENCES "simulation_runs" ("simulation_id")
);

CREATE TABLE "simulation_runs" (
  "simulation_id" TEXT,
  "created_at" TIMESTAMP,
  "scenario_name" TEXT,
  "scenario_type" TEXT,
  "baseline_or_scenario" TEXT,
  "random_seed" NUMERIC,
  "start_time" TIMESTAMP,
  "end_time" TIMESTAMP,
