CREATE TABLE "visits" (
  "visit_id" TEXT,
  "patient_id" TEXT,
  "arrival_time" TIMESTAMP,
  "arrival_source" TEXT,
  "acuity_level" NUMERIC,
  "service_line" TEXT,
  "disposition" TEXT,
  "departure_time" TIMESTAMP,
  "wait_minutes" INTEGER,
  "length_of_stay_hours" NUMERIC,
  "triage_time" TIMESTAMP,
  "provider_seen_time" TIMESTAMP,
  "decision_to_admit_time" TIMESTAMP,
  "ward_bed_assigned_time" TIMESTAMP,
  "boarding_minutes" NUMERIC,
  "admit_target_dept" TEXT,
  "lwbs_reason" TEXT,
  "chief_complaint_group" TEXT,
  "data_source" TEXT,
  PRIMARY KEY ("visit_id"),
  FOREIGN KEY ("patient_id") REFERENCES "patients" ("patient_id"),
  CHECK ("wait_minutes" IS NULL OR "wait_minutes" >= 0),
  CHECK ("length_of_stay_hours" IS NULL OR "length_of_stay_hours" >= 0),
  CHECK ("boarding_minutes" IS NULL OR "boarding_minutes" >= 0),
  CHECK ("acuity_level" IS NULL OR "acuity_level" BETWEEN 1 AND 5),
  CHECK ("departure_time" IS NULL OR "departure_time" >= "arrival_time")
);

